WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, COUNT_IF(device_code = 'DV-04') AS dv_04_events, SIZE(COLLECT_SET(device_code)) AS num_device_codes, COUNT(*) AS cnt, ROUND(AVG(pressure), 2) AS avg_pressure, MAX(reading_ts) AS last_reading_ts, BIT_AND(status_bits) AS status_bits_bit_and FROM sessions_device_readings GROUP BY DATE_TRUNC('DAY', reading_ts) ORDER BY avg_pressure DESC
